import json
from pathlib import Path

lab = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(encoding="utf-8")
)

# ১) Fit Training Row থেকে হাতে-কলমে Popularity Count c_i হিসাব করি
pop_counts = {}
for u, movie_id, rating, ts in lab["model"]["train"]:
    if rating >= 4.0:
        pop_counts[movie_id] = pop_counts.get(movie_id, 0) + 1

ranked_pairs = []
for movie_id, count in pop_counts.items():
    ranked_pairs.append((-count, movie_id))
ranked_pairs.sort()
print("Top 5 Fit Popularity (movieId, positives):")
for neg_c, movie_id in ranked_pairs[:5]:
    print(f"  movieId={movie_id:4d} -> positives={-neg_c}")

# ২) Validation ও Audit Warm প্যানেলে Baselines বনাম Selected Policy তুলনা করি
selected = lab["policy"]["selected"]
for role in ["validation", "audit"]:
    for name in ["popularity", "user_cf", selected]:
        card = lab["scorecards"][role][name]["warm"]
        print(f"{role:10s} | {name:10s} | Recall={card['recall']:.5f} | NDCG={card['ndcg']:.5f}")

assert (
    lab["scorecards"]["audit"]["user_cf"]["warm"]["ndcg"]
    > lab["scorecards"]["audit"][selected]["warm"]["ndcg"]
)
print("Confirmed: single user_cf outperforms selected rrf_cf on Audit NDCG@10!")

import json
from pathlib import Path

lab = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(encoding="utf-8")
)
manifest = lab["manifest"]
manifest_fields = ["model_version", "model_sha256", "catalog_sha256", "feature_schema", "policy_sha256"]
artifact_parts = []
for f in manifest_fields:
    artifact_parts.append(str(manifest[f]))
artifact_sig = ":".join(artifact_parts)

# ১) প্রথম Warm ও প্রথম Cold Audit User বেছে নিই (ঠিক workflow-এর মতো)
warm_row = None
cold_row = None
for row in lab["roles"]["audit"]:
    if warm_row is None and row["train_count"] > 0 and len(row["eligible"]) > 0:
        warm_row = row
    if cold_row is None and row["train_count"] == 0:
        cold_row = row
requests = [
    (warm_row, "rrf_equal"),
    (warm_row, "rrf_cf"),
    (warm_row, "rrf_equal"),
    (cold_row, "rrf_equal"),
    (warm_row, "rrf_cf"),
]

def run_cache_replay(mode, budget=50):
    cache = {}
    hits = 0
    rejected = 0
    computations = 0
    for row, policy in requests:
        full_sig = f"{artifact_sig}:{row['user']}:{row['history_sha256']}:{policy}:{budget}:seen=all-fit"
        if mode == "complete":
            key = full_sig
        elif mode == "shared_user":
            key = f"{artifact_sig}:{policy}:{budget}:seen=all-fit"
        else:
            key = f"{artifact_sig}:{row['user']}:{row['history_sha256']}:{budget}:seen=all-fit"

        prev = cache.get(key)
        is_rejected = (prev is not None) and (prev["signature"] != full_sig)
        is_hit = (prev is not None) and (not is_rejected)
        # Uncached deterministic reference-এর সাথে মিলিয়ে রাখি
        expected_ranked = row["rankings"][policy]
        ranked = prev["ranked"] if is_hit else expected_ranked
        assert ranked == expected_ranked
        cache[key] = {"signature": full_sig, "ranked": ranked}
        if is_hit:
            hits += 1
        else:
            computations += 1
        if is_rejected:
            rejected += 1
    return {"requests": len(requests), "hits": hits, "rejected": rejected, "computations": computations}

for mode in ["complete", "shared_user", "omit_policy"]:
    res = run_cache_replay(mode)
    saved = lab["cache"][mode]
    for k_name in ["requests", "hits", "rejected", "computations"]:
        assert res[k_name] == saved[k_name]
    print(f"mode={mode:11s} | {res}")
